import 'package:flutter/material.dart';import 'package:platform_core_frontend/features/super_admin/data/super_admin_repository.dart';import 'package:platform_core_frontend/features/super_admin/models/admin_masjid_request_model.dart';import 'package:platform_core_frontend/features/super_admin/presentation/widgets_common.dart';import 'package:platform_core_frontend/shared/widgets/loading_view.dart';
class AdminMasjidRequestDetailScreen extends StatelessWidget{const AdminMasjidRequestDetailScreen({super.key,required this.id,this.initial});final String id;final AdminMasjidRequestModel? initial;@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Request Details')),body:FutureBuilder(future:SuperAdminRepository().getMasjidRequest(id),initialData: initial,builder:(c,s){if(!s.hasData)return const LoadingView();final r=s.data!;return ListView(padding:const EdgeInsets.all(16),children:[AdminStatusChip(r.status),Text('Masjid Details',style:Theme.of(c).textTheme.titleLarge),InfoRow('Masjid',r.masjidName),InfoRow('Country',r.country),InfoRow('State',r.state),InfoRow('Address',r.address),InfoRow('Phone',r.contactNo),InfoRow('Welcome Message',r.welcomeMsg),InfoRow('Description',r.description),const Divider(),Text('Requester Details',style:Theme.of(c).textTheme.titleLarge),InfoRow('Requester',r.requesterName),InfoRow('Phone',r.requesterPhone),InfoRow('Email',r.requesterEmail),const Divider(),Text('Imam Details',style:Theme.of(c).textTheme.titleLarge),InfoRow('Imam',r.imamName),InfoRow('Phone',r.imamPhone),InfoRow('Email',r.imamEmail),const Divider(),Text('Committee Members',style:Theme.of(c).textTheme.titleLarge),...r.committeeMembers.map((m)=>InfoRow('Member',m.toString())),InfoRow('Reason',r.rejectionReason),InfoRow('Created',r.createdAt)]);}));}
